<?php
require dirname(__DIR__).'/app/bootstrap.php';require_login();require dirname(__DIR__).'/app/layout.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$old=required_text('current_password',200);$new=required_text('new_password',200);if(!password_verify($old,current_user()['password_hash']))throw new DomainException('Your current password is incorrect.');if(strlen($new)<12)throw new DomainException('Use a password of at least 12 characters.');if($new!==($_POST['confirm_password']??''))throw new DomainException('New passwords do not match.');query('UPDATE users SET password_hash=? WHERE id=? AND business_id=?',[password_hash($new,PASSWORD_DEFAULT),current_user()['id'],bid()]);audit('password.changed','user',(int)current_user()['id']);$_SESSION=[];session_regenerate_id(true);flash('Your password has been changed. Sign in again to continue.');redirect('login.php');}catch(DomainException $ex){$error=$ex->getMessage();}}
page_start('Your profile','Your account, access and security in one place.');error_notice($error);?><section class="panel form-panel"><div class="cell-person"><span class="avatar blue"><?= e(initials(current_user()['name'])) ?></span><div><h2><?= e(current_user()['name']) ?></h2><span class="muted"><?= e(current_user()['email']) ?> · <?= e(ucfirst(current_user()['role'])) ?></span></div></div><p>Last sign-in: <?= e(current_user()['last_login']??'Current session') ?> · Sessions expire after 30 minutes of inactivity.</p><h3>Change password</h3><form method="post"><?php csrf_field(); ?><div class="form-grid"><?php field('current_password',['Current password','password',true]);field('new_password',['New password (12+ characters)','password',true]);field('confirm_password',['Confirm new password','password',true]); ?></div><div class="form-actions"><button class="btn primary">Update password</button></div></form><form method="post" action="logout.php"><div class="form-actions"><?php csrf_field(); ?><button class="btn danger"><?= icon('logout') ?> Sign out</button></div></form></section><?php page_end(); ?>
